cd /Users/lambertbouley/Claude/lbtbly-fitness-app
SQL="do \$\$ declare column_row record; found bigint; begin create temporary table if not exists bp_matches (place text, sample text) on commit preserve rows; delete from bp_matches; for column_row in select table_name, column_name from information_schema.columns where table_schema = 'public' and data_type in ('text','character varying','json','jsonb') loop execute format('insert into bp_matches select %L, left(%I::text, 120) from %I where %I::text ~* %L', column_row.table_name || '.' || column_row.column_name, column_row.column_name, column_row.table_name, column_row.column_name, '(mmhg|tension arterielle|pression arterielle|blood pressure|systolic|diastolic|128/82)'); end loop; select count(*) into found from bp_matches; raise notice 'blood pressure matches: %', found; end \$\$; select coalesce(string_agg(place || ' = ' || sample, ' | '), 'none') from bp_matches"
docker compose exec -T -e SQL="$SQL" db sh -c 'psql -U "$POSTGRES_USER" -d vernier_scratch -At -c "$SQL"'
